def string_xor(a: str, b: str) -> str:
    # Ensure both strings are of the same length
    max_len = max(len(a), len(b))
    a = a.zfill(max_len)
    b = b.zfill(max_len)

    # Perform XOR operation
    result = []
    for i in range(max_len):
        if a[i] == b[i]:
            result.append('0')
        else:
            result.append('1')

    # Join the list into a string and return
    return ''.join(result)
